  SRL16E #(
    .INIT(16'hFFFF)) 
    POR_SRL_I
       (.A0(1'b1),
        .A1(1'b1),
        .A2(1'b1),
        .A3(1'b1),
        .CE(1'b1),
        .CLK(aclk),
        .D(1'b0),
        .Q(Q));
  FDRE #(
    .INIT(1'b0)) 
